#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Visuelle effekter i terminalen. Kun standardbiblioteket.

Kjør med:  python3 smile.py
Gjør terminalen stor / fullskjerm for best resultat.

Du kan også importere den i spillet ditt:

    from smile import smiling_time
    smiling_time()
"""

import base64
import random
import shutil
import sys
import time
import zlib

# Animasjon: 13 rammer, 60 millisekunder hver.
IMG_W = 400
IMG_H = 300
N_FRAMES = 13
FRAME_MS = 60

# Halvblokken ▀: forgrunn = topp-piksel, bakgrunn = bunn-piksel.
BLOKK = "\u2580"


def last_rammer():
    """Pakk ut de 13 RGB-rammene (zlib + base64, bare standardbiblioteket)."""
    data = zlib.decompress(base64.b64decode(_DATA))
    n = IMG_W * IMG_H * 3
    return [data[i * n:(i + 1) * n] for i in range(N_FRAMES)]


def skaler(src, sw, sh, dw, dh):
    """Skaler et RGB-bilde til dw x dh med nærmeste nabo (nærmeste piksel)."""
    if dw == sw and dh == sh:
        return src if isinstance(src, bytes) else bytes(src)
    ut = bytearray(dw * dh * 3)
    for y in range(dh):
        sy = y * sh // dh
        src_rad = sy * sw * 3
        dst_rad = y * dw * 3
        for x in range(dw):
            sx = x * sw // dw
            si = src_rad + sx * 3
            di = dst_rad + x * 3
            ut[di] = src[si]
            ut[di + 1] = src[si + 1]
            ut[di + 2] = src[si + 2]
    return bytes(ut)


def _farge(r, g, b, lys, tint, flash):
    r = int(r * lys * tint[0])
    g = int(g * lys * tint[1])
    b = int(b * lys * tint[2])
    if flash == "red":
        # rødt blitz, men bildet skal fortsatt synes
        r = min(255, r + 170)
        g = g // 5
        b = b // 6
    elif flash == "white":
        r = min(255, 220 + r // 5)
        g = min(255, 220 + g // 5)
        b = min(255, 220 + b // 5)
    if r < 0:
        r = 0
    elif r > 255:
        r = 255
    if g < 0:
        g = 0
    elif g > 255:
        g = 255
    if b < 0:
        b = 0
    elif b > 255:
        b = 255
    return r, g, b


def tegn_ramme(piksler, bw, bh, kolonner, rader, oks=0, oky=0,
               lys=1.0, tint=(1.0, 1.0, 1.0), flash=None, bunntekst=None):
    """Bygg én skjermramme som en enkelt streng.

    \033[H flytter markøren hjem uten å tømme skjermen. Vi skriver hele
    rammen på én gang, så det ikke flimrer.
    """
    # Én linje i reserve, så terminalen ikke scroller
    bilde_rader = max(4, rader - 1)
    lerret_w = kolonner
    lerret_h = bilde_rader * 2
    start_x = (lerret_w - bw) // 2 + oks
    start_y = (lerret_h - bh) // 2 + oky * 2  # oky er i rader (2 piksler)

    def hent(x, y):
        ix = x - start_x
        iy = y - start_y
        if ix < 0 or iy < 0 or ix >= bw or iy >= bh:
            return 0, 0, 0
        i = (iy * bw + ix) * 3
        return _farge(piksler[i], piksler[i + 1], piksler[i + 2], lys, tint, flash)

    linjer = []
    for rad in range(bilde_rader):
        # Siste rad kan byttes ut med "GAME OVER"
        if bunntekst and rad == bilde_rader - 1:
            pad = max(0, (kolonner - len(bunntekst)) // 2)
            hoyre = max(0, kolonner - pad - len(bunntekst))
            linjer.append(
                "\033[0m" + " " * pad
                + "\033[1;38;2;255;30;30m" + bunntekst
                + "\033[0m" + " " * hoyre
            )
            continue
        y0 = rad * 2
        y1 = y0 + 1
        deler = []
        forrige = None
        for x in range(lerret_w):
            t = hent(x, y0)
            u = hent(x, y1)
            # nesten svart: vanlig mellomrom (raskere, og bakgrunnen blir ren)
            if t[0] < 5 and t[1] < 5 and t[2] < 5 and u[0] < 5 and u[1] < 5 and u[2] < 5:
                if forrige != "blank":
                    deler.append("\033[0m ")
                    forrige = "blank"
                else:
                    deler.append(" ")
            else:
                key = t + u
                if forrige != key:
                    deler.append(
                        "\033[38;2;{};{};{}m\033[48;2;{};{};{}m{}".format(
                            t[0], t[1], t[2], u[0], u[1], u[2], BLOKK
                        )
                    )
                    forrige = key
                else:
                    deler.append(BLOKK)
        deler.append("\033[0m")
        linjer.append("".join(deler))
    # \033[H = home (øverst til venstre)
    return "\033[H" + "\n".join(linjer)


def tekst_ramme(kolonner, rader, linjer, farge=(200, 180, 90)):
    """Sentrer noen tekstlinjer på svart skjerm (brukt til 'Natt 5')."""
    bilde_rader = max(4, rader - 1)
    start = (bilde_rader - len(linjer)) // 2
    r, g, b = farge
    fargekode = "\033[38;2;{};{};{}m".format(r, g, b)
    ut = []
    for i in range(bilde_rader):
        if start <= i < start + len(linjer):
            t = linjer[i - start]
            pad = max(0, (kolonner - len(t)) // 2)
            hoyre = max(0, kolonner - pad - len(t))
            ut.append("\033[0m" + " " * pad + fargekode + t + "\033[0m" + " " * hoyre)
        else:
            ut.append("\033[0m" + " " * kolonner)
    return "\033[H" + "\n".join(ut)


def lag_stoy(w, h, tetthet=0.08):
    """Tilfeldig 'kamera-statisk' (grå prikker på svart)."""
    buf = bytearray(w * h * 3)
    n = int(w * h * tetthet)
    for _ in range(n):
        i = random.randrange(w * h) * 3
        v = random.randint(14, 80)
        buf[i] = min(255, v + random.randint(0, 20))
        buf[i + 1] = v
        buf[i + 2] = max(0, v - random.randint(0, 12))
    return bytes(buf)


def skriv(ramme, bjelle=False):
    if bjelle:
        ramme += "\a"  # \a får terminalen til å pipe
    sys.stdout.write(ramme)
    sys.stdout.flush()


def smiling_time(intro=False, game_over=False):
    """Spill av effekten. intro=True gir 'Natt 5' og mørke først."""
    try:
        sys.stdout.reconfigure(encoding="utf-8")
    except Exception:
        pass

    kolonner, rader = shutil.get_terminal_size(fallback=(80, 24))
    kolonner = max(40, kolonner)
    rader = max(12, rader)

    # Skjul markøren og tøm skjermen. I finally vises markøren alltid igjen,
    # også om du avbryter med Ctrl+C.
    sys.stdout.write("\033[?25l\033[2J\033[3J\033[H")
    sys.stdout.flush()

    try:
        if intro:
            skriv(tekst_ramme(kolonner, rader, ["Natt 5 ... 3:00 AM"]))
        t_intro = time.monotonic()

        rammer = last_rammer()

        # Tilpass bildet til terminalen uten å strekke det (svart rundt om nødvendig)
        bilde_rader = max(4, rader - 1)
        lerret_w = kolonner
        lerret_h = bilde_rader * 2
        skala = min(lerret_w / float(IMG_W), lerret_h / float(IMG_H))
        dw = max(2, int(IMG_W * skala))
        dh = max(2, int(IMG_H * skala))
        if dh % 2:
            dh = max(2, dh - 1)
        skalert = [skaler(fr, IMG_W, IMG_H, dw, dh) for fr in rammer]

        if intro:
            time.sleep(max(0.0, 2.0 - (time.monotonic() - t_intro)))

            # Noen sekunder i mørket med statisk, tilfeldig hvor lenge (så du ikke vet når)
            slutt = time.monotonic() + random.uniform(2.2, 3.6)
            while time.monotonic() < slutt:
                stoy = lag_stoy(lerret_w, lerret_h, tetthet=random.uniform(0.04, 0.14))
                skriv(tegn_ramme(stoy, lerret_w, lerret_h, kolonner, rader))
                time.sleep(0.06)

            # Kort helt svart før animasjonen
            skriv(tegn_ramme(b"\x00\x00\x00", 1, 1, kolonner, rader))
            time.sleep(0.28)

        # Spill av GIF-rammene med original tid (60 ms)
        toppunkt = 9  # toppunktet i animasjonen
        for i, fr in enumerate(skalert):
            t0 = time.monotonic()
            oks = oky = 0
            flash = None
            bjelle = False
            if i >= toppunkt:
                # risting som blir sterkere mot slutten
                styrke = (i - toppunkt + 1) / float(N_FRAMES - toppunkt)
                maks_x = int(1 + 3 * styrke)
                maks_y = int(1 + 2 * styrke)
                oks = random.randint(-maks_x, maks_x)
                oky = random.randint(-maks_y, maks_y)
                if i >= 10 and i % 2 == 0:
                    flash = "red"
                if i == 10:
                    bjelle = True
            skriv(
                tegn_ramme(fr, dw, dh, kolonner, rader, oks, oky, flash=flash),
                bjelle=bjelle,
            )
            vent = FRAME_MS / 1000.0 - (time.monotonic() - t0)
            if vent > 0:
                time.sleep(vent)

        # Extra blitz og risting på siste ramme
        siste = skalert[-1]
        for flash in ("red", None, "white", "red", None, "red"):
            oks = random.randint(-4, 4)
            oky = random.randint(-2, 2)
            skriv(
                tegn_ramme(siste, dw, dh, kolonner, rader, oks, oky, flash=flash),
                bjelle=(flash == "red"),
            )
            time.sleep(0.07)

        if game_over:
            skriv(tegn_ramme(siste, dw, dh, kolonner, rader, bunntekst="GAME OVER"))
            time.sleep(2.0)
        else:
            time.sleep(0.6)
    finally:
        # Tøm skjermen og vis markøren igjen, så spillet kan fortsette
        sys.stdout.write("\033[0m\033[2J\033[3J\033[H\033[?25h")
        sys.stdout.flush()


if __name__ == "__main__":
    smiling_time()


